+	d := &decoder{r: asByteReader(r)}
+	l.decode(d)
+	return d.err
+}
+
+func (l *LaxLoop) decode(d *decoder) {
+	version := d.readInt8()
+	if d.err != nil {
+		return
+	}
+	if version != encodingVersion {
+		d.err = fmt.Errorf("can't decode version %d; my version: %d", version, encodingVersion)
+		return
+	}
+	nvertices := d.readUint32()
+	if d.err != nil {
+		return
+	}
+	if nvertices > maxEncodedVertices {
+		d.err = fmt.Errorf("too many vertices (%d; max is %d)", nvertices, maxEncodedVertices)
+		return
+	}
+	pts := make([]Point, 0, min(int(nvertices), 4096))
+	for range nvertices {
+		v := Point{r3.Vector{
+			X: d.readFloat64(),
+			Y: d.readFloat64(),
+			Z: d.readFloat64(),
+		}}
+		if d.err != nil {
+			return
+		}
+		if math.IsNaN(v.X) || math.IsInf(v.X, 0) || math.IsNaN(v.Y) || math.IsInf(v.Y, 0) || math.IsNaN(v.Z) || math.IsInf(v.Z, 0) {
+			d.err = errors.New("invalid vertex coordinates")
+			return
+		}
+		pts = append(pts, v)
+	}
+	l.numVertices = int(nvertices)
+	l.vertices = pts
+}
