-	return ChainPosition{p.cumulativeVertices[nextLoop] - p.cumulativeVertices[1], e - p.cumulativeVertices[nextLoop-1]}
+	return ChainPosition{nextLoop - 1, e - p.cumulativeVertices[nextLoop-1]}
+}
+
+// Encode encodes the LaxPolygon.
+func (p *LaxPolygon) Encode(w io.Writer) error {
+	e := &encoder{w: w}
+	p.encode(e)
+	return e.err
+}
+
+func (p *LaxPolygon) encode(e *encoder) {
+	if p.numLoops > maxEncodedLoops {
+		e.err = fmt.Errorf("too many loops (%d; max is %d)", p.numLoops, maxEncodedLoops)
+		return
+	}
+	numVerts := p.numVertices()
+	if numVerts > maxEncodedVertices {
+		e.err = fmt.Errorf("too many vertices (%d; max is %d)", numVerts, maxEncodedVertices)
+		return
+	}
+	e.writeInt8(encodingVersion)
+	e.writeUvarint(uint64(p.numLoops))
+	for i := 0; i < p.numLoops; i++ {
+		e.writeUvarint(uint64(p.numLoopVertices(i)))
+	}
+	for i := 0; i < numVerts; i++ {
+		v := p.vertices[i]
+		e.writeFloat64(v.X)
+		e.writeFloat64(v.Y)
+		e.writeFloat64(v.Z)
+	}
+}
+
+// Decode decodes the LaxPolygon.
+func (p *LaxPolygon) Decode(r io.Reader) error {
+	d := &decoder{r: asByteReader(r)}
+	p.decode(d)
+	return d.err
+}
+
+func (p *LaxPolygon) decode(d *decoder) {
+	version := d.readInt8()
+	if d.err != nil {
+		return
+	}
+	if version != encodingVersion {
+		d.err = fmt.Errorf("can't decode version %d; my version: %d", version, encodingVersion)
+		return
+	}
+	numLoops := d.readUvarint()
+	if d.err != nil {
+		return
+	}
+	if numLoops > maxEncodedLoops {
+		d.err = fmt.Errorf("too many loops (%d; max is %d)", numLoops, maxEncodedLoops)
+		return
+	}
+
+	var cumVerts []int
+	var totalVertices uint64
+	if numLoops > 1 {
+		cumVerts = make([]int, 0, min(int(numLoops)+1, 4096))
+		cumVerts = append(cumVerts, 0)
+	}
+	var loop0Verts int
+	for i := uint64(0); i < numLoops; i++ {
+		nv := d.readUvarint()
+		if d.err != nil {
+			return
+		}
+		if nv > maxEncodedVertices || totalVertices+nv > maxEncodedVertices {
+			d.err = fmt.Errorf("too many vertices (%d; max is %d)", totalVertices+nv, maxEncodedVertices)
+			return
+		}
+		totalVertices += nv
+		if numLoops == 1 {
+			loop0Verts = int(nv)
+		} else {
+			cumVerts = append(cumVerts, int(totalVertices))
+		}
+	}
+
+	var pts []Point
+	if totalVertices > 0 || numLoops == 1 {
+		pts = make([]Point, 0, min(int(totalVertices), 4096))
+	}
+	for range totalVertices {
+		var v Point
+		v.X = d.readFloat64()
+		v.Y = d.readFloat64()
+		v.Z = d.readFloat64()
+		if d.err != nil {
+			return
+		}
+		if math.IsNaN(v.X) || math.IsInf(v.X, 0) || math.IsNaN(v.Y) || math.IsInf(v.Y, 0) || math.IsNaN(v.Z) || math.IsInf(v.Z, 0) {
+			d.err = fmt.Errorf("invalid vertex coordinates")
+			return
+		}
+		pts = append(pts, v)
+	}
+
+	*p = LaxPolygon{
+		numLoops:           int(numLoops),
+		vertices:           pts,
+		numVerts:           loop0Verts,
+		cumulativeVertices: cumVerts,
+	}
 }

